// Constant class names that aren't generated by Vanilla Extract. Only add
// class names to this file when you need to reference CSS classes without
// pulling in the full `client/styles` dependency.
//
// For example:
//
// - `shared/content` needs constant class names for its ProseMirror schema
//   which it defines how content nodes should be rendered to DOM in `toDOM`
//   functions. `shared/content` can't depend on `client/styles` since
//   `shared/content` is used by the server.
//
// - `client/blobs/helpers` needs constant class names for the classes it
//   references because its compiled to a script which is added as an embedded
//   `<script>` tag that can run on server-side render. We can't depend on
//   `client/styles` since that adds a massive amount of duplicated code to the
//   embedded `<script>` tag.

import {HighlightColor} from "~/shared/design/core/highlight_color.js";

/**
 * When you put this class on an element then all children will use "elevated"
 * colors. This has no effect in light mode but in dark mode elevated colors are
 * slightly lighter. Since we can't use shadows in dark mode to simulate depth we
 * instead give surfaces that are "higher up" a lighter background. We use this
 * for peeks since peeks contain arbitrary content we need to implement
 * these lighter backgrounds at the color system level.
 */
export const greyElevated1ClassName =
    process.env.NODE_ENV !== "production" ? "greyElevated1" : "ge1";

/**
 * When you put this class on an element then all children will use "elevated"
 * colors. This has no effect in light mode but in dark mode elevated colors are
 * slightly lighter. Since we can't use shadows in dark mode to simulate depth we
 * instead give surfaces that are "higher up" a lighter background. We use this
 * for hovering overlays.
 */
export const greyElevated2ClassName =
    process.env.NODE_ENV !== "production" ? "greyElevated2" : "ge2";

